/* V6: complete formerly missing flows. All domain changes are confined to this prototype. */
function safeUrl(url){try{const x=new URL(url,location.href);return ['http:','https:'].includes(x.protocol)?x.href:null;}catch{return null;}}
function reviewLink(id,params={}){const u=new URL(location.href);u.hash=id+(params.id?':'+encodeURIComponent(params.id):'');return u.href;}
async function copyReviewLink(id,params={}){const text=reviewLink(id,params);try{await navigator.clipboard.writeText(text);toast(L('Ссылка скопирована','Link copied'),{type:'ok'});}catch{sheet(()=>({title:L('Поделиться ссылкой','Share link'),body:`<label class="field"><span>${L('Скопируй адрес','Copy this address')}</span><input class="inp" readonly value="${esc(text)}" autofocus></label><p class="note">${L('Ссылка не включает личные ответы или закрытые материалы.','The link excludes private answers and restricted media.')}</p>`}));}}
ACT.shareProfile=()=>copyReviewLink(cur().p.id?'P01':'P03',{id:cur().p.id});ACT.evShare=()=>copyReviewLink('E03',{id:cur().p.id});
function downloadFile(text,type,name){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
ACT.addCal=()=>{const e=EV(cur().p.id);if(!e||e.cancelled){toast(L('Событие недоступно','Event unavailable'),{type:'warn'});return;}const dt=x=>new Date(x).toISOString().replace(/[-:]/g,'').replace(/\.\d{3}Z/,'Z');const txt=s=>String(s||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/[,;]/g,'\\$&');downloadFile(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//FetUre//V6//EN','BEGIN:VEVENT','UID:'+cur().p.id+'@feture','DTSTAMP:'+dt(Date.now()),'DTSTART:'+dt(e.start),'DTEND:'+dt(e.end),'SUMMARY:'+txt(T(e.title)),'DESCRIPTION:'+txt(L('Подробности участия — в FetUre.','Participation details are in FetUre.')),'END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar','feture-event.ics');closeSheet();toast(L('Файл календаря скачан — открой его для добавления','Calendar file downloaded — open it to add the event'),{type:'ok'});};
ACT.k7export=()=>{downloadFile(JSON.stringify({profile:S.me,posts:S.myPosts,postEdits:S.postEdits,communityApplications:Object.entries(S.communityRequests).flatMap(([community,requests])=>requests.filter(x=>x.p==='me').map(x=>({community,...x}))),requests:S.reqOut,events:S.extraEvents,messages:S.threads},null,2),'application/json','feture-v6-data.json');toast(L('Данные этой сессии скачаны','Session data downloaded'),{type:'ok'});};
const exportRender=SC.K07.render;SC.K07.render=(...args)=>exportRender(...args).replace(L('Профиль, карта, дневник, публикации и переписка — архивом на почту. Обычно до 24 часов.','Profile, map, journal, posts and messages — an archive to your email. Usually within 24 hours.'),L('Скачай профиль, интересы, публикации, сохранённые правки и переписку из текущей сессии. Храни файл в безопасном месте.','Download your profile, interests, posts, saved changes and conversations from this session. Keep the file somewhere safe.')).replace(L('Запросить архив','Request archive'),L('Скачать JSON','Download JSON'));

// Requests and grants share a single model, expired / blocked entries cannot be opened.
const requestAccess=ACT.reqAccess;ACT.reqAccess=a=>{const id=a.dataset.v||cur().p.id;if(!PEOPLE[id]||isBlocked(id)){toast(L('Профиль недоступен','Profile unavailable'),{type:'warn'});return;}const g=receivedGrant(id);if(g){go('P08',{id});return;}return requestAccess(a);};
// V8: private profile renders inside the profile (s-profile.js privSection).

// V7: private photos/video live in P04 «Приватное» (s-profile.js); M01/M03 are aliases.

// Couple: an invitation never means consent or merges private accounts.
ACT.pairLink=()=>go('Q01');
SC.Q01={title:()=>L('Связь пары','Couple connection'),render:()=>`${bar(L('Связь пары','Couple connection'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><div class="opt-hero"><span class="lockc">${I.couple}</span></div><h2 class="t">${L('Вместе — только по взаимному решению','Together, only by mutual agreement')}</h2><p class="lead">${L('Личные аккаунты, интересы и переписки останутся раздельными. Приглашение не открывает чужие материалы.','Personal accounts, interests and conversations stay separate. An invitation does not open private media.')}</p>${S.pair?.status==='active'?`<div class="card list">${linkRow({go:'Q03',icon:'couple',title:L('Общий профиль','Couple profile')})}${linkRow({go:'Q05',icon:'lock',title:L('Общие доступы','Shared grants')})}${linkRow({go:'Q06',icon:'x',cls:'danger',title:L('Разъединить пару','Unlink couple')})}</div>`:S.pairInvite?`<div class="alert info">${I.clock}<span>${L('Приглашение отправлено. Ждём отдельного согласия второго человека.','Invitation sent. Waiting for the other person’s separate consent.')}</span></div><button class="btn soft" data-act="v6PairCancel">${L('Отозвать приглашение','Withdraw invitation')}</button>`:`<button class="btn primary" data-go="Q02">${L('Пригласить партнёра','Invite partner')}</button>`}</div></div>`};
SC.Q02={title:()=>L('Пригласить в пару','Invite partner'),render:()=>`${bar(L('Пригласить в пару','Invite partner'),{back:1,sm:1})}<div class="view nodock cta1"><div class="wrap">${field({name:'partner',label:L('Ник партнёра','Partner nickname'),ph:'@nickname'})}<p class="note">${L('Каждый подтверждает связь в своём аккаунте. До двух подтверждений общего профиля нет.','Each person confirms in their own account. There is no couple profile until both confirm.')}</p></div></div><div class="ctabar"><div class="wrap"><button class="btn primary" data-act="v6PairInvite">${L('Отправить приглашение','Send invitation')}</button></div></div>`};
ACT.v6PairInvite=a=>{const r=cur(),nick=fv('partner').trim().replace(/^@/,'');if(!/^[a-z0-9_.]{3,20}$/i.test(nick)||nick===S.me.nick){setErr('partner',L('Укажи другой корректный ник','Enter another valid nickname'));return;}run(a,()=>{S.pairInvite={nick,status:'pending'};autoResolve();r.dirty=false;go('Q01',{}, {replace:true});},{ok:L('Приглашение отправлено','Invitation sent')});};
ACT.v6PairCancel=()=>{S.pairInvite=null;refresh();};
/* Q03 — the couple profile: a layer over two separate accounts. Each person keeps own chats, likes and grants. */
const pairName=()=>S.pair?T(S.pair.name):'';
SC.Q03={title:()=>L('Общий профиль','Couple profile'),render:()=>{const P=S.pair;if(P?.status!=='active')return unavailable();const pr=P.proposal;
 const member=id=>`<button class="li" ${profGo(id)}>${av(id,'')}<span class="tx"><b>${esc(pname(id))}${nameBadges(person(id))}</b><small>${id==='me'?L('ты · личный профиль отдельно','you · personal profile is separate'):L('партнёр · свой аккаунт','partner · own account')}</small></span>${I.chev}</button>`;
 return `${bar(L('Общий профиль','Couple profile'),{back:1,sm:1,actions:`<button class="ibtn" data-go="Q04" aria-label="${L('Предложить изменения','Propose changes')}">${I.edit}</button>`})}<div class="view nodock"><div class="wrap">
 <div class="pair-hero">${av('me','lg')}${av(P.with,'lg')}</div><h2 class="t center">${esc(pairName())}</h2><p class="note center">${L(`вместе в FetUre с ${F.date(P.since)}`,`a couple on FetUre since ${F.date(P.since)}`)}</p>
 ${pr?`<div class="alert warn mt16">${I.clock}<span><b>${L(`${pname(pr.by)} предлагает новое описание`,`${pname(pr.by)} proposes a new description`)}</b>«${esc(T(pr.text))}»<span class="row g8 mt8"><button class="btn sm primary" data-act="pairProposal" data-v="yes">${L('Согласиться','Approve')}</button><button class="btn sm soft" data-act="pairProposal" data-v="no">${L('Отклонить','Decline')}</button></span></span></div>`:''}
 ${grp(L('Описание пары','About the couple'),`<p class="bio">${esc(T(P.desc))}</p>`,{foot:L('Меняется только с согласия обоих.','Changes only with both agreeing.')})}
 ${grp(L('Правила знакомства','How to approach us'),`<p class="bio">${esc(T(P.rules))}</p>`)}
 ${grp(L('Двое — два аккаунта','Two people, two accounts'),member('me')+member(P.with),{list:1})}
 ${grp(L('Что общее, а что у каждого своё','What’s shared and what’s personal'),`<div class="fact"><i class="g">${I.check}</i><span>${L('Общее: описание, правила, совместные публикации и общие доступы — каждый шаг подтверждают оба.','Shared: description, rules, joint posts and joint grants — both confirm every step.')}</span></div><div class="fact"><i class="v">${I.lock}</i><span>${L('Личное: чаты, симпатии, баночки, расширенный профиль и личные доступы. Партнёр их не видит.','Personal: chats, likes, jars, private profile and personal grants. Your partner can’t see them.')}</span></div>`)}
 <div class="card list mt16">${linkRow({go:'Q05',icon:'lock',title:L('Общие доступы','Shared grants'),val:String(P.grants.length)})}${linkRow({go:'P01',p:{id:P.with},icon:'me',title:L(`Личный профиль ${pname(P.with)}`,`${pname(P.with)}’s own profile`)})}${linkRow({go:'Q06',icon:'x',cls:'danger',title:L('Разъединить пару','Unlink couple')})}</div>
 </div></div>`;}};
ACT.pairProposal=a=>{const P=S.pair;if(!P?.proposal)return;const yes=a.dataset.v==='yes';run(a,()=>{if(yes)P.desc=P.proposal.text;P.proposal=null;refresh();},{ms:400,ok:yes?L('Описание обновлено — согласились оба','Description updated — you both agreed'):L('Предложение отклонено. Описание прежнее','Proposal declined. The description stays')});};
SC.Q04={title:()=>L('Изменения пары','Couple changes'),render:()=>`${bar(L('Изменения пары','Couple changes'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${field({name:'pairName',label:L('Название пары','Couple name')})}<button class="btn primary" data-act="v6PairChange">${L('Отправить на согласование','Request partner approval')}</button><p class="note">${L('Публикация произойдёт после отдельного подтверждения второго человека.','Publishing requires the other person’s separate approval.')}</p></div></div>`};
ACT.v6PairChange=()=>{if(!fv('pairName').trim())return;S.pairProposal=fv('pairName').trim();cur().dirty=false;toast(L('Предложение ожидает согласия партнёра','Proposal awaits partner consent'),{type:'info'});};
SC.Q05={title:()=>L('Общие доступы','Shared grants'),render:()=>{const P=S.pair;const st=v=>v==='yes'?`<span class="pill ok">${I.check}${L('да','yes')}</span>`:`<span class="pill wait">${I.clock}${L('ждёт','pending')}</span>`;
 const rows=(P?.grants||[]).filter(g=>!isBlocked(g.p)).map(g=>`<div class="li">${whoLink(g.p,'')}<span class="tx"><b>${esc(pname(g.p))}</b><small>${esc(SCOPE_TXT(g.scopes))}${g.until?` · ${esc(F.left(g.until))}`:''}</small><span class="row g8 mt8"><span class="note">${L('Ты','You')}</span>${st(g.me)}<span class="note">${esc(pname(P.with))}</span>${st(g.partner)}</span></span></div>`).join('');
 return `${bar(L('Общие доступы','Shared grants'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><p class="lead">${L('Общий доступ открывается, только когда согласились оба. Пока второй не ответил, человек ничего не видит.','A joint grant opens only when both agree. Until the second person answers, nothing is visible.')}</p>
 ${rows?`<div class="card list">${rows}</div>`:empty('lock',L('Общих доступов нет','No shared grants'),L('Новые материалы и каждый доступ требуют двух решений. Личные доступы управляются отдельно.','New media and every grant need two decisions. Personal grants are managed separately.'))}
 <button class="btn soft mt16" data-go="P07">${L('Мои личные доступы','My personal grants')}</button></div></div>`;}};
SC.Q06={title:()=>L('Разъединить пару','Unlink couple'),render:()=>`${bar(L('Разъединить пару','Unlink couple'),{back:1,sm:1})}<div class="view nodock"><div class="wrap"><p class="lead">${L('Общий профиль перестанет действовать, общие доступы закроются. Личные аккаунты и данные останутся.','The couple profile and shared grants stop. Personal accounts and data remain.')}</p><button class="btn danger" data-act="v6PairUnlink">${L('Разъединить','Unlink')}</button></div></div>`};
ACT.v6PairUnlink=()=>ask({title:L('Разъединить пару?','Unlink the couple?'),ok:L('Разъединить','Unlink'),danger:true}).then(ok=>{if(ok){S.pair=null;S.pairInvite=null;go('Q01',{}, {replace:true});}});SC.Q07={...SC.Q01,title:()=>L('Связь остановлена','Connection stopped')};

// Community management never grants personal chat access.
SC.C11={title:()=>L('Заявки сообщества','Community requests'),valid:p=>ownsCommunity(p.id),render:p=>{if(!ownsCommunity(p.id))return unavailable();const all=S.communityRequests[p.id]||[],pending=all.filter(x=>x.status==='pending'),done=all.filter(x=>x.status!=='pending');const t=p.t==='history'?'history':'pending',list=t==='history'?done:pending;
 return `${bar(L('Заявки сообщества','Community requests'),{back:1,sm:1,sub:esc(T(COMMUNITIES[p.id].name))})}<div class="view nodock"><div class="wrap">${seg([['pending',L('Новые','New'),pending.length||''],['history',L('Решения','Decisions'),done.length||'']],t,'cRequestsTab')}
 <p class="note mt12">${L('Ответы видны только ведущим. Одобрение даёт участие в сообществе, но не открывает личный чат или расширенный профиль.','Only hosts can see the answers. Approval grants community membership, never a private chat or private profile.')}</p>
 ${list.map(req=>`<section class="card mt12">${personRow(req.p)}<p class="note">${F.rel(req.updated||req.t)}${req.status!=='pending'?' · '+({approved:L('Одобрено','Approved'),declined:L('Отклонено','Declined'),withdrawn:L('Отозвана','Withdrawn')}[req.status]||''):''}</p><p style="white-space:pre-wrap">${esc(T(req.answer))}</p>${req.status==='pending'?`<div class="row g8"><button class="btn soft" data-act="cRequestDecision" data-v="${esc(req.id)}" data-status="declined">${L('Отклонить','Decline')}</button><button class="btn primary" data-act="cRequestDecision" data-v="${esc(req.id)}" data-status="approved">${L('Одобрить','Approve')}</button></div>`:''}</section>`).join('')||empty('doc',t==='history'?L('Решений пока нет','No decisions yet'):L('Новых заявок нет','No new requests'),L('Ответы участников видны только ведущим этого сообщества.','Applicant answers are visible only to this community’s hosts.'))}</div></div>`;}};
ACT.cRequestsTab=a=>setP('t',a.dataset.v);
ACT.cRequestDecision=a=>{const owner=S,session=S.session,route=cur(),id=route.p.id,status=a.dataset.status,req=(S.communityRequests[id]||[]).find(x=>x.id===a.dataset.v),community=COMMUNITIES[id],applicant=req?.p,reviewedAnswer=JSON.stringify(req?.answer);
 const allowed=()=>S===owner&&S.session===session&&cur()===route&&route.id==='C11'&&ownsCommunity(id)&&COMMUNITIES[id]===community&&community.status!=='review'&&(S.communityRequests[id]||[]).includes(req)&&req?.status==='pending'&&req.p===applicant&&JSON.stringify(req.answer)===reviewedAnswer&&req.p!=='me'&&!!PEOPLE[req.p];
 if(!['approved','declined'].includes(status)||!allowed())return;const submit=()=>{if(!allowed())return;let changed=false;return run(status==='approved'?a:null,()=>{if(!allowed())return;req.status=status;req.updated=Date.now();if(status==='approved'&&!(community.seedMembers||[]).includes(req.p))(S.communityMembers[id]??=new Set()).add(req.p);changed=true;refresh();},{ok:()=>changed?(status==='approved'?L('Участие одобрено','Membership approved'):L('Заявка отклонена','Request declined')):null});};
 if(status==='declined')return ask({title:L('Отклонить заявку?','Decline this request?'),text:L('Участие в сообществе не откроется. Это не блокировка профиля.','Community membership will not be granted. This does not block the profile.'),ok:L('Отклонить','Decline'),danger:true}).then(ok=>ok?submit():undefined);return submit();};
SC.C12={title:()=>L('Модерация сообщества','Community moderation'),valid:p=>ownsCommunity(p.id),render:p=>!ownsCommunity(p.id)?unavailable():`${bar(L('Модерация сообщества','Community moderation'),{back:1,sm:1})}<div class="view nodock"><div class="wrap">${empty('shield',L('Очередь обращений пуста','Report queue is empty'),L('Проверяй обсуждения, ответы и правила. Личные данные участников ведущим недоступны.','Review discussions, replies and rules. Hosts cannot access members’ private data.'))}${linkRow({go:'C03',p:{id:p.id,t:'rules'},icon:'doc',title:L('Правила сообщества','Community rules')})}</div></div>`};
const manageCommunity=SC.C10.render;SC.C10.render=(p,r)=>manageCommunity(p,r).replace('data-act="soon"','data-go="C11" data-id="'+p.id+'"').replace('data-act="soon"','data-go="C12" data-id="'+p.id+'"').replace('data-act="soon"','data-act="v6CommunityEdit"').replace('data-act="soon"','data-act="v6Hosts"');
ACT.v6CommunityEdit=()=>{if(!ownsCommunity(cur().p.id))return;const c=COMMUNITIES[cur().p.id];S.ui.communityDraft={name:T(c.name),desc:T(c.desc),rules:c.rules.map(T).join('\n')};sheet(()=>({title:L('Описание и правила','Description and rules'),body:`<label class="field"><span>${L('Название','Name')}</span><input class="inp" id="v6cn" value="${esc(S.ui.communityDraft.name)}"></label>${rteField({name:'v6cd',local:'v6cd',value:S.ui.communityDraft.desc,label:L('Описание','Description'),max:500})}<label class="field"><span>${L('Правила — по одному на строку','Rules — one per line')}</span><textarea class="inp" id="v6cr">${esc(S.ui.communityDraft.rules)}</textarea></label>`,foot:`<button class="btn primary" data-act="v6CommunitySave">${L('Сохранить','Save')}</button>`}));};
ACT.v6CommunitySave=()=>{if(!ownsCommunity(cur().p.id))return;const c=COMMUNITIES[cur().p.id],name=$('#v6cn').value.trim(),desc=rteVal('v6cd').trim(),rules=$('#v6cr').value.trim();if(name.length<3||!rules){toast(L('Нужны название и правила','A name and rules are required'),{type:'err'});return;}c.name={ru:name,en:name};c.desc={ru:desc,en:desc};c.rules=rules.split('\n').map(x=>({ru:x,en:x}));closeSheet();refresh();};
ACT.v6Hosts=()=>ownsCommunity(cur().p.id)&&sheet(()=>({title:L('Ведущие сообщества','Community hosts'),body:`<div class="card list">${communityHostIds(cur().p.id).map(id=>personRow(id)).join('')||personRow('me')}</div><p class="note">${L('Назначение ролей требует отдельной проверки прав. Роль ведущего не открывает личные профили участников.','Assigning roles needs a separate permission check. A host role never opens members’ private profiles.')}</p>`}));

SC.K08={title:()=>L('Ссылки и сравнения','Links and comparisons'),render:()=>`${bar(L('Ссылки и сравнения','Links and comparisons'),{back:1,sm:1})}<div class="view nodock compact"><div class="wrap">${empty('link',L('Активных приватных ссылок нет','No active private links'),L('Публичная ссылка не передаёт доступ. Приватные ссылки должны иметь выбранные разделы, срок и отзыв.','A public link never transfers access. Private links need selected sections, expiry and revocation.'))}<button class="btn soft" data-act="shareProfile">${L('Поделиться публичным профилем','Share public profile')}</button></div></div>`};
const settingsRender=SC.K01.render;SC.K01.render=(...a)=>settingsRender(...a).replace('<div class="sec">'+L('Поддержка','Support')+'</div>',`<div class="card list">${linkRow({go:'K08',icon:'link',title:L('Ссылки и сравнения','Links and comparisons')})}</div><div class="sec">${L('Поддержка','Support')}</div>`);
const helpText=()=>({shield:[L('Подтверждение возраста','Age verification'),L('Дата рождения — самодекларация. Отдельная проверка даёт доступ к ограниченным функциям и не публикует документы.','Date of birth is self-declared. Separate verification enables restricted features and never publishes documents.')],lock:[L('Кто видит личное','Who sees private details'),L('Только выбранный человек, выбранные разделы и только на указанный срок. Доступ можно отозвать бесплатно.','Only the selected person sees the selected sections for the chosen duration. Revocation is free.')],heart:[L('Личные чаты','Private conversations'),L('Чат открывает взаимная личная симпатия. Подписка, посты, участие и приватный доступ не дают права написать.','Only mutual personal likes open a chat. Following, posts, attendance and private grants never enable messaging.')],cal:[L('Офлайн-встречи','In-person meetings'),L('Проверь организатора, условия, время и способы связи. Сообщи близкому план встречи. При непосредственной опасности обратись в местную экстренную службу.','Check the organiser, requirements, time and contact details. Tell someone you trust your plan. In immediate danger, contact your local emergency service.')],crown:[L('Подписка','Membership'),L('Premium увеличивает квоты и историю. Приватность, отказ, отзыв и ответная симпатия бесплатны. Покупка не даёт чужого согласия.','Premium expands quotas and history. Privacy, refusal, revocation and liking back are free. Purchasing never buys consent.') ]});
const helpRender=SC.S01.render;SC.S01.render=(...a)=>{let html=helpRender(...a);for(const key of ['shield','lock','heart','cal','crown'])html=html.replace('data-act="soon"',`data-act="v6Help" data-v="${key}"`);return html.replace(L('При опасности звони 112.','In danger, call 112.'),L('При опасности обратись в местную экстренную службу.','In danger, contact your local emergency service.'));};
ACT.v6Help=a=>{const [title,text]=helpText()[a.dataset.v];sheet(()=>({title,body:`<p class="lead">${text}</p>`}));};

// Hash links update in place. Copy links are real; no sensitive form input enters URLs.
const renderV6=render;render=function(dir,keep){renderV6(dir,keep);const r=cur();const hash=r.id+(r.p.id?':'+encodeURIComponent(r.p.id):'');history.replaceState(history.state,'','#'+hash);};

ACT.sharePost=a=>copyReviewLink('F05',{id:a?.dataset?.v||cur().p.id});

